export const japaneseNPCs=[[{"id": 1541239, "sourceRole": "Duty teacher", "sourceLines": ["That bell is not background music. Move!", "Jarvis, your mind can race. Your body needs to sit down."], "role": "当番の先生", "lines": ["チャイムはBGMじゃない。聞こえたら動く！", "Jarvis、頭は走ってもいい。体は席に戻しなさい。"]}, {"id": 1012103, "sourceRole": "Classmate", "sourceLines": ["Five minutes of break, four minutes in line. Peak efficiency.", "I am listening. My eyes just left school early."], "role": "クラスメート", "lines": ["休み5分、行列4分。見事な時間管理だね。", "聞いてるよ。目だけ先に下校したんだ。"]}], [{"id": 2040052, "sourceRole": "Librarian", "sourceLines": ["Quiet. Even your inner monologue needs to whisper.", "Vocabulary will not walk into your brain. Open the book."], "role": "司書", "lines": ["静かに。心の中の独り言も小さな声で。", "単語は勝手に頭へ入らないよ。まず本を開こう。"]}, {"id": 1012104, "sourceRole": "Study partner", "sourceLines": ["One more page, then a break. I said that three pages ago.", "My vocabulary and my drowsiness: only one is growing."], "role": "受験仲間", "lines": ["このページが終わったら休憩。もう3ページ前から言ってる。", "単語力と眠気、増えているのは後者だけ。"]}], [{"id": 2111000, "sourceRole": "Language teacher", "sourceLines": ["You can fix your grammar. Stop waiting for perfect.", "Japanese today, please. Pointing at the menu does not count."], "role": "語学の先生", "lines": ["文法は直せます。完璧を待たずに話そう。", "今日も日本語で。注文を指さしだけで済ませないでね。"]}, {"id": 1012108, "sourceRole": "Language student", "sourceLines": ["I get it! Probably. Maybe. Just nod for now.", "Honorifics detected. Brain buffering."], "role": "語学学校の学生", "lines": ["分かった！ たぶん。きっと。とりあえずうなずこう。", "敬語が来た。頭が読み込み中。"]}], [{"id": 1002006, "sourceRole": "Cafe chef", "sourceLines": ["That proposal smells good. So does coffee. Serve it hot.", "I got your ideas. Please get the cups off that table too."], "role": "カフェのシェフ", "lines": ["企画もいい香りだけど、コーヒーは熱いうちにね。", "アイデアは受け取ったよ。ついでにテーブルのカップもお願い。"]}, {"id": 1052004, "sourceRole": "Cafe manager", "sourceLines": ["Hold the sugar on that idea. Show me the costs.", "Secret quest: still be smiling after the rush."], "role": "カフェの店長", "lines": ["アイデアに砂糖はまだいらない。原価表を見せて。", "今日の隠しクエスト。繁忙時間の後も笑顔でいること。"]}], [{"id": 1011000, "sourceRole": "Shopkeeper", "sourceLines": ["The first thing up in a new shop is the rent.", "The sign is up. The rest is on you."], "role": "商店街の店主", "lines": ["開店で最初に目覚めるのは夢じゃなく家賃だよ。", "看板は付いた。ここからは風水じゃなく君の出番。"]}, {"id": 1012105, "sourceRole": "Neighboring shop owner", "sourceLines": ["Welcome! Browsing is fine. Bring your wallet next time.", "Foot traffic and sales are two different things."], "role": "隣の店主", "lines": ["いらっしゃい！ 見るだけでもどうぞ。次は財布も忘れずに。", "人通りと売上は別の話だね。"]}], [{"id": 2152006, "sourceRole": "Market vendor", "sourceLines": ["Where did yesterday’s queue go?", "Hype fades. The stock in the fridge does not."], "role": "市場の店主", "lines": ["昨日並んでいた人たち、今日はどこへ？", "ブームは去るけど、冷蔵庫の在庫は去ってくれない。"]}, {"id": 2110002, "sourceRole": "Next-door vendor", "sourceLines": ["Watch the books as closely as the customers.", "Today’s special: the owner’s optimism. Free of charge."], "role": "隣の露店主", "lines": ["お客さんだけじゃなく、帳簿も見よう。", "本日の特売、店主の楽観。無料です。"]}], [{"id": 2092001, "sourceRole": "Courier", "sourceLines": ["Route changed? Recalculate. Standing still delivers nothing.", "The delivery box has insulation. Life has no navigation."], "role": "配達員", "lines": ["ルートが変わったら再計算。立っているだけじゃ届かない。", "配送箱には保温機能。人生の曲がり角にはナビがない。"]}, {"id": 2152004, "sourceRole": "Kitchen cook", "sourceLines": ["Dine-in is closed. The stove did not ask for a break.", "Wherever the order comes from, do not let it go cold."], "role": "厨房の料理人", "lines": ["店内営業は休み。でもコンロは休みを頼んでない。", "どこから来た注文でも、冷まさないのが大事。"]}], [{"id": 2110000, "sourceRole": "Repair technician", "sourceLines": ["Power off first! Confidence is not an insulating glove.", "Plug the cable in before questioning your life."], "role": "修理技師", "lines": ["まず電源を切って！ 自信は絶縁手袋にならないよ。", "人生を疑う前に、ケーブルを挿そう。"]}, {"id": 2012017, "sourceRole": "Mechanical assistant", "sourceLines": ["All the parts are here. Desk space is missing.", "One screw left over? Do not call it a spare yet."], "role": "機械助手", "lines": ["部品は全部ある。足りないのは机の広さ。", "ネジが1本余った？ 予備と決めつけるのは早い。"]}], [{"id": 2111007, "sourceRole": "Test-market seller", "sourceLines": ["Test a small batch. The warehouse is not a wishing well.", "Side quest failed? At least keep the save file."], "role": "試験販売の店主", "lines": ["まず少量で試そう。倉庫は願いをかなえる池じゃない。", "サイドクエスト失敗？ せめてセーブは残そう。"]}, {"id": 2152017, "sourceRole": "Passing trader", "sourceLines": ["Some tuition comes without a receipt. Keep the lesson.", "Try another approach. Stop staring lovingly at the shelf."], "role": "通りがかりの商人", "lines": ["領収書のない授業料もある。学びは持ち帰ろう。", "売れなければ方法を変えよう。棚を見つめても始まらない。"]}], [{"id": 1092000, "sourceRole": "Head chef", "sourceLines": ["Brands can multiply. Stove burners cannot.", "Your brain is launching brands. Your hands need to watch this pot!"], "role": "厨房のシェフ", "lines": ["ブランドは増やせるけど、コンロの数は増えないよ。", "頭は新ブランドのことでも、手はこの鍋を見て！"]}, {"id": 1082001, "sourceRole": "Pickup courier", "sourceLines": ["Boss, dreams can simmer. This order cannot.", "I wait for food. The customer waits for me. Such patience. Probably."], "role": "受け取りの配達員", "lines": ["店長、夢はじっくり煮込めるけど、この注文は急いで。", "私は料理を待ち、お客さんは私を待つ。みんな辛抱強い。たぶん。"]}], [{"id": 2040050, "sourceRole": "Studio technician", "sourceLines": ["Check the specs first. RGB cannot hide a problem.", "Another upgrade? Check that you are not the bottleneck."], "role": "スタジオの技師", "lines": ["まず仕様を確認。RGBでは問題を隠せないよ。", "またアップグレード？ 自分がボトルネックじゃないか確認して。"]}, {"id": 2012018, "sourceRole": "Testing assistant", "sourceLines": ["Booting is the beginning. Stability is the test.", "The fan is quiet. Hopefully it has power."], "role": "テスト助手", "lines": ["起動は始まり。安定して動いてこそだよ。", "ファンが静かだ。電源がつながっていればいいけど。"]}], [{"id": 1002103, "sourceRole": "Harbor captain", "sourceLines": ["Dock when you need to. Even captains check the fuel.", "Bring your luggage. Leave the warehouse behind."], "role": "港の船長", "lines": ["必要な時は港へ戻ろう。船長だって燃料を見る。", "荷物だけ持って行こう。倉庫ごと船に積まなくていい。"]}, {"id": 1082101, "sourceRole": "Dock worker", "sourceLines": ["Next departure soon. Hesitation is not checked luggage.", "Boxes have direction labels. People sometimes need them too."], "role": "港の作業員", "lines": ["次の便が出るよ。迷いは預け荷物にできない。", "箱には向きの表示がある。人にも時々必要だね。"]}], [{"id": 2152011, "sourceRole": "Language classmate", "sourceLines": ["Lovely sea view. The waves will not wash your homework away.", "English today. Even complaining counts as practice."], "role": "語学クラスの仲間", "lines": ["海はきれい。でも宿題は波で流れないよ。", "今日も英語で。愚痴だって練習になる。"]}, {"id": 2152010, "sourceRole": "Coastal coach", "sourceLines": ["The sun is hot. Keep your brain from overheating.", "Sunscreen first. Conquering waves comes later."], "role": "海辺のコーチ", "lines": ["日差しが強い。頭までオーバーヒートさせないで。", "波に挑む前に、日焼け止めを塗ろう。"]}], [{"id": 2152001, "sourceRole": "Drill instructor", "sourceLines": ["Jarvis! Your brain can take side quests. Your formation cannot!", "I said push-ups, not lying down to reflect on life!", "Eyes front! The Resistance is still training. Who told you to rest?", "Left, right, left! Start a business solo. March in formation!"], "role": "教官", "lines": ["Jarvis！ 頭でサイドクエストはいいが、隊列は守れ！", "腕立て伏せだ！ 伏せたまま人生を考える時間じゃない！", "よそ見するな！ レジスタンスもまだ訓練中だ。誰が休めと言った！", "いち、に、いち！ 起業は一人でも、行進は足並みをそろえろ！"]}, {"id": 2152002, "sourceRole": "Resistance · mage", "sourceLines": ["Mana has potions. Shaky legs do not.", "The instructor has not called a halt. No clocking out."], "role": "レジスタンス・魔法使い", "lines": ["魔力には薬がある。震える脚にはまだない。", "教官が止めるまでは、勝手に退勤しないよ。"]}, {"id": 2152003, "sourceRole": "Resistance · archer", "sourceLines": ["Aim at the target, not at break time.", "Crossbow steady. Knees negotiable."], "role": "レジスタンス・弩使い", "lines": ["狙うのは的。休憩時間じゃない。", "弩は安定。膝は別の話。"]}, {"id": 2152005, "sourceRole": "Resistance · mechanic", "sourceLines": ["Mech serviced. My legs need maintenance next.", "This is squat training, not standby mode!"], "role": "レジスタンス・メカニック", "lines": ["機体の整備は終わった。次は脚の整備を。", "待機モードじゃない。スクワットの訓練だ！"]}], [{"id": 1032104, "sourceRole": "English teacher", "sourceLines": ["Ask if you do not understand. Nodding earns no speaking score.", "Grammar can be fixed. Do not mute yourself."], "role": "英語の先生", "lines": ["分からなければ質問。うなずくだけでは会話点になりません。", "文法は直せます。自分をミュートしないで。"]}, {"id": 1012001, "sourceRole": "Reading room librarian", "sourceLines": ["Today’s progress cannot just be “showed up.”", "Going abroad? Prepare for tomorrow’s quiz first."], "role": "閲覧室の司書", "lines": ["今日の進捗が「来ました」だけでは困るよ。", "留学の準備？ まず明日の小テストから。"]}], [{"id": 9201052, "sourceRole": "Graduate mentor", "sourceLines": ["The desert is dry. Keep the report free of filler too.", "Lovely model. Where are the assumptions?"], "role": "大学院の指導者", "lines": ["砂漠は乾いている。レポートも水増ししないように。", "きれいなモデルだね。前提条件はどこ？"]}, {"id": 1012109, "sourceRole": "Graduate classmate", "sourceLines": ["Forty degrees outside. The deadline is still ice cold.", "Refill the coffee. Add the sources too."], "role": "大学院の仲間", "lines": ["外は40度。でも締切は冷酷だね。", "コーヒーのおかわりも、出典の追加も忘れずに。"]}], [{"id": 2110004, "sourceRole": "Site engineer", "sourceLines": ["It works on paper. Walk the site anyway.", "Hard hat on. Slides will not protect your head."], "role": "現場の技術者", "lines": ["図で通れても、現場でも歩いて確認しよう。", "ヘルメットを着けて。スライドは頭を守らない。"]}, {"id": 2111008, "sourceRole": "Project researcher", "sourceLines": ["Sources before conclusions. Even a good guess needs checking.", "A clear question can beat ten more pages."], "role": "プロジェクト研究者", "lines": ["結論の前に出典。良い推測でも検証しよう。", "問いを明確にする方が、10ページ増やすより役立つこともある。"]}], [{"id": 1002101, "sourceRole": "Crossroads traveler", "sourceLines": ["There is blank space on the map. Walk to reveal it.", "No spoilers for the next chapter. You can still pack."], "role": "分かれ道の旅人", "lines": ["地図には空白がある。歩いて開いていこう。", "次の章のネタバレはないけど、荷造りはできる。"]}, {"id": 1012009, "sourceRole": "Supply merchant", "sourceLines": ["Supplies ready? Courage is not a meal.", "Game saved. Stop daydreaming in front of the portal."], "role": "補給の商人", "lines": ["補給は済んだ？ 勇気だけでは食べられないよ。", "セーブ完了。ポータルの前でずっとぼんやりしないで。"]}]];
